// Registers one command-line argument definition into Storm's command list.
// @oracle SCmdRegisterArgument
// @oracle-source Storm export vector SCmdRegisterArgument @100cbcac -> code 10008240 = the traceback-named function .SCmdRegisterArgument, in Mac PPC 1.10b Storm
// @rename-basis Behaviour plus a cross-architecture body match. .SCmdRegisterArgument is reached from .SCmdRegisterArgList @10008550 with all eight PowerPC argument registers r3..r10 loaded; this function has the same eight arguments and is called from SCmdRegisterArgList 006c4e50 with the same eight values in the same order, (rec[0], rec[1], rec[2], 0, 0, 1, -1, rec[3]).
// @former-name SCMD_RegisterCommand
BOOL __stdcall SCmdRegisterArgument(uint32_t dwFlags, uint32_t dwId, char * szText, void * pVariable, uint32_t dwVariableBytes, uint32_t dwSetValue, uint32_t dwSetMask, SCMDCALLBACK pfnCallback);
// Registers an array of dwCount command-argument definitions by calling SCmdRegisterArgument once per 16-byte record. NULL list -> SetLastError(0x57); stops and returns FALSE on the first failed registration.
// @oracle SCmdRegisterArgList
// @oracle-source Storm export vector SCmdRegisterArgList @100cbca4 -> code 10008550 in Mac PPC 1.10b Storm
// @rename-basis Instruction-for-instruction cross-architecture match, the strongest available here. PPC 10008550: null-check the list pointer, else SetLastError(0x57) and return 0; loop dwCount times over 0x10-byte records loading +0, +4, +8, +0xc into r3, r4, r5, r10 with r6=0, r7=0, r8=1, r9=-1, and calling .SCmdRegisterArgument; bail out returning 0 on any failure; return 1. This function is the same loop with the same constants: SCmdRegisterArgument(rec[0], rec[1], rec[2], 0, 0, 1, -1, rec[3]) over records advanced by 4 dwords.
// @former-name FOG_AppendToBuffer (invented, and in the wrong module - it is not Fog and it appends to nothing)
// @namespace-fix moved Global -> Storm::Source::SCMD
BOOL __stdcall SCmdRegisterArgList(struct ARGLIST * pArgList, uint32_t nCount);
// Tokenises a command string and dispatches each token against the registered command list, optionally skipping the first token. Reports 0x8510006d through the error callback when a required argument was not supplied.
